export const DESTINATIONS: any = DESTINATIONS_RAW.map(dest => ({
    ...dest,
    attractionsList: dest.attractions.map(attName =>
        PLACES.find(p => p.name.toLowerCase() === attName.toLowerCase())
    ).filter((x): x is Place => !!x)
}));

export const ATTRACTIONS = PLACES.filter(p => p.isFeatured || p.isPopular).map(p => ({
    id: p.id,
    name: p.name,
    slug: p.slug,
    location: p.city,
    category: p.category,
    description: p.description,
    image: p.images[0],
    rating: p.rating,
    reviews: p.reviews,
    entryFee: {
        indian: p.ticket.indian,
        foreigner: p.ticket.foreigner
    },
    timing: `${p.timing.open} - ${p.timing.close}`,
    bestTime: p.bestTimeToVisit.months,
    duration: p.visitDuration.recommended,
    tags: p.tags,
    highlights: p.highlights,
    isFeatured: p.isFeatured
}));




